
import React from "react";
import { useState } from "react";
import { useEffect } from "react";
import { useStateContext } from "../../contexts/ContextProvider";
import * as Yup from "yup";
import { useFormik } from "formik";

import useApi from "../../hooks/useApi";

import { toast, ToastContainer } from "react-toastify";
import 'react-toastify/dist/ReactToastify.css';
import { Input } from "@heroui/react";
import customerOrdersApi from "../../api/retailers/customerOrdersApi";

const PaymentDetails = ({
  paymentMethodName,
  isPaid,
  paymentMethodImage,
  handleRefresh,
  onPaymentMethodChange,
  transformedPaymentMethods,
  paymentMethod,
  paymentMethodHandler,
  order,
}) => {
  const { currentColor } = useStateContext();

  const [showPaymentMethodSelector, setshowPaymentMethodSelector] =
    useState(false);


  const handleChangePaymentMethod = () => {
    setshowPaymentMethodSelector(!showPaymentMethodSelector);
  };


  const updateOrderDetailsApi = useApi(customerOrdersApi.customerOrdersActionAdmin);

 
  const formik = useFormik({
    initialValues: {
      shipping_amount: order ? order.shipping_amount : 0.0,
    },

    validationSchema: Yup.object({
      shipping_amount: Yup.number()
        .min(0, "Cannot be negative")
        .required()
        .label("Shipping cost required"),
    }),
    onSubmit: async(values, { resetForm }) => {
      const result = await updateOrderDetailsApi.request({
        action: "UpdateRetailerOrder",
        retailer_order_details: {
          retailer_order_id: order.id,
         
          shipping_amount: values.shipping_amount,
        },
      });
      if(result.ok){
        toast.success(result.data.response_message)
      }

      resetForm();
    },
  });



 

  return (
    <>
      <section className="grid grid-cols-1 md:grid-cols-4 gap-2 p-2 shadow-md  border border-zinc-200 rounded my-2 md:my-0 bg-slate-50">
        <div className=" shadow-md rounded-md">
          <h2>Payment method</h2>
          <ToastContainer position="bottom-center" theme="colored" />

         {order ? <h2>{order.selected_payment_method_title}</h2>: <h2>UNKNOWN</h2>}

        </div>
        <div className=" shadow-md rounded-md ">
          <h2>Delivery Method</h2>

          <p>{order && order.delivery_method}</p>
        </div>
        <div className=" shadow-md rounded-md ">
          <h2>Payment status</h2>
          {order.payment ? (
            <p>PAID</p>
          ) : (
           <p>NOT PAID</p>
          )}
          
        </div>
        <div className=" shadow-md rounded-md ">
          <h2>Shipping Cost</h2>
          <h2>{order.shipping_cost}</h2>
          <div>
         

          </div>
        </div>
      </section>
    </>
  );
};

export default PaymentDetails;
