import { useState, useRef, useEffect } from "react";
import ClientDetails from "./ClientDetails";
import Dates from "./Dates";
import Footer from "./Footer";
import Header from "./Header";
import MainDetails from "./MainDetails";
import Notes from "./Notes";
import Table from "./Table";
import TableForm from "./TableForm";
import ReactToPrint from "react-to-print";
import { DonateButton } from "./buttons";
import PaymentDetails from "./PaymentDetails";
import { useStateContext } from "../../contexts/ContextProvider";
import { titleCase } from "../../helpers/authUtils";

// import { useDispatch, useSelector } from "react-redux";
import servicesHelpers from "../../helpers/servicesHelpers";

import { Errors } from "..";
import { Button } from "antd";
import { useNavigate } from "react-router-dom";

function RetailerOrderInvoice({ order, showForm = false, handleRefresh }) {
  const [name, setName] = useState("");
  const [address, setAddress] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [bankName, setBankName] = useState("");
  const [bankAccount, setBankAccount] = useState("");
  const [website, setWebsite] = useState("");
  const [clientName, setClientName] = useState("");
  const [clientAddress, setClientAddress] = useState("");
  const [invoiceNumber, setInvoiceNumber] = useState("");
  const [invoiceDate, setInvoiceDate] = useState("");
  const [dueDate, setDueDate] = useState("");
  const [notes, setNotes] = useState("");
  const [description, setDescription] = useState("");
  const [quantity, setQuantity] = useState("");
  const [price, setPrice] = useState("");
  const [discountTotal, setdiscountTotal] = useState("");
  const [netPriceTotal, setnetPriceTotal] = useState("");
  const [amount, setAmount] = useState("");
  const [list, setList] = useState([]);
  const [total, setTotal] = useState(0);
  const [width] = useState(641);
  const [isPaid, setisPaid] = useState(false);
  const [paymentMethodName, setpaymentMethodName] = useState("");
  const [paymentMethodImage, setpaymentMethodImage] = useState("");
  const [paymentMethod, setpaymentMethod] = useState();
  const [shippingAmount, setshippingAmount] = useState(0);
  const componentRef = useRef();
  // const paymentMethods = useSelector((state) => state.Utilities.paymentMethods);
  // const errors = useSelector((state) => state.RetailerCart.errors);
  const [transformedPaymentMethods, settransformedPaymentMethods] = useState(
    []
  );

  const [paymentMethods, setpaymentMethods] = useState([]);
  const [errors, seterrors] = useState([]);
  const { currentColor } = useStateContext();
  // const dispatch = useDispatch();

  const handlePrint = () => {
    window.print();
  };

  useEffect(() => {
    if (window.innerWidth < width) {
      alert("Place your phone in landscape mode for the best experience");
    }
  }, [width]);

  useEffect(() => {
    if (order) {
      setName(order.title);
      setEmail(order.entity_details?.email);
    }

    console.log("ORDER AT INVOICE", order);
  }, [order]);

  useEffect(() => {
    if (order.item.title) {
      setName(order.item.title);
      setEmail(order.item.entity_details?.email);
      setPhone(order.entity_details?.phone);
    }

    if (order) {
      console.log("my order", order);
      setClientAddress(order.customer_phone);
      setClientName(`${order.item.retailer_title}`);
      setshippingAmount(order.shipping_amount);
      setpaymentMethod(order.payment_method_details);

      setDueDate(order.item?.created);
      setInvoiceDate(order.item?.created);
      setInvoiceNumber(titleCase(order.item.reference_number));
      let Items = [];
      console.log("order irems", order.item.order_items);

      order.item.order_items.map((x) =>
        Items.push({
          id: x.id,
          description: `${x.product_title}-${x.units_per_pack}'s`,
          pack_selling_price: x.pack_selling_price,
          amount: x.item_net_price_total,
          quantity: x.purchased_quantity.toString(),
          discount: x.item_price_discount_total,
          price: x.pack_selling_price * x.purchased_quantity,
          net_amount: x.item_net_price_total,
        })
      );
      console.log("Items", Items);
      setList(Items);
      setTotal(
        order.item.order_items
          .reduce((acc, item) => acc + parseFloat(item.item_price_total), 0)
          .toFixed(2)
      );
      setAmount(
        order.item.order_items
          .reduce((acc, item) => acc + parseFloat(item.pack_selling_price), 0)
          .toFixed(2)
      );
      setdiscountTotal(
        order.item.order_items
          .reduce(
            (acc, item) => acc + parseFloat(item.item_price_discount_total),
            0
          )
          .toFixed(2)
      );
      setnetPriceTotal(
        order.item.order_items
          .reduce((acc, item) => acc + parseFloat(item.item_price_total), 0)
          .toFixed(2)
      );
      setpaymentMethodName(
        order.item.payment_method_title
          ? order.item.payment_method_title
          : "N/A"
      );
      if (order.item.retailer_payment) {
        setisPaid(true);
      }
      if (
        order.item.payment_method_details
          ? order.payment_method_details.images &&
            order.payment_method_details.images.length
          : ""
      ) {
        setpaymentMethodImage(
          order.payment_method_details
            ? order.payment_method_details.images[0].image
            : ""
        );
      }
    }
  }, [order]);

  useEffect(() => {
    // dispatch(getPaymentMethods());
  }, []);

  useEffect(() => {
    if (paymentMethods && paymentMethods.length > 0) {
      const tpm = servicesHelpers.paymentMethodsTransform(paymentMethods);
      settransformedPaymentMethods(tpm);
    }
  }, [paymentMethods]);

  const paymentMethodHandler = (e) => {
    // console.log("Change payment method", e.value);
    // dispatch(
    //   customerOrderAction({
    //     action: "ChangeOrderPaymentMethod",
    //     customer_order: order.id,
    //     payment_method: e.value,
    //   })
    // );
  };

  const mounted = useRef(false);

  useEffect(() => {
    mounted.current = true;

    return () => {
      // dispatch(resetRedux());
      mounted.current = false;
    };
  }, []);

  const navigate = useNavigate();
  const handleReceiveOrder = () => {
    navigate(`/retailers/requisitions/orders/items/${order.item.id}`);
  };

  return (
    <>
      <main className=" grid grid-cols-1 lg:max-w-4xl m-auto shadow-xl ">
        {/* Invoice Preview */}
        {errors && errors.length && <Errors errors={errors} />}
        <div className="invoice__preview bg-white p-2 rounded">
          <div className="flex flex-row">
            <ReactToPrint
              trigger={() => (
                <button
                  style={{ backgroundColor: currentColor }}
                  className="btn w-1/4 bg-blue-500 ml-5 text-white font-bold py-2 px-8 rounded shadow border-2 border-blue-500 hover:bg-transparent hover:text-blue-100 transition-all duration-300"
                >
                  Print / Download
                </button>
              )}
              content={() => componentRef.current}
            />
            <Button
              onClick={handleReceiveOrder}
              style={{ backgroundColor: currentColor }}
              className=" btn w-1/4 bg-blue-500 ml-5 text-white font-bold py-2 px-8 rounded shadow border-2 border-blue-500 hover:bg-transparent hover:text-blue-100 transition-all duration-300"
            >
              Receive Inventory
            </Button>
          </div>

          <div ref={componentRef} className="px-5">
            <Header handlePrint={handlePrint} />

            <MainDetails name={name} address={address} />

            <ClientDetails
              clientName={clientName}
              clientAddress={clientAddress}
            />

            <Dates
              invoiceNumber={invoiceNumber}
              invoiceDate={invoiceDate}
              dueDate={dueDate}
            />
            {transformedPaymentMethods && (
              <PaymentDetails
                order={order}
                isPaid={isPaid}
                paymentMethodName={paymentMethodName}
                paymentMethodImage={paymentMethodImage}
                handleRefresh={handleRefresh}
                transformedPaymentMethods={transformedPaymentMethods}
                paymentMethod={paymentMethod}
                paymentMethodHandler={paymentMethodHandler}
              />
            )}

            <Table
              shippingAmount={shippingAmount}
              description={description}
              quantity={quantity}
              price={price}
              amount={amount}
              list={list}
              setList={setList}
              total={total}
              setTotal={setTotal}
              discountTotal={discountTotal}
              netPriceTotal={netPriceTotal}
            />

            <Notes notes={notes} />

            <Footer
              name={name}
              address={address}
              website={website}
              email={email}
              phone={phone}
              bankAccount={bankAccount}
              bankName={bankName}
            />
          </div>
          {/* <button
            onClick={() => setShowInvoice(false)}
            className="mt-5 bg-blue-500 text-white font-bold py-2 px-8 rounded shadow border-2 border-blue-500 hover:bg-transparent hover:text-blue-500 transition-all duration-300"
          >
            Edit Information
          </button> */}
        </div>
      </main>
    </>
  );
}

export default RetailerOrderInvoice;
